('onboarding_lists','{\"forms\":{\"title\":\"COM_EMUNDUS_ONBOARD_FORMS\",\"tabs\":[{\"title\":\"COM_EMUNDUS_FORM_MY_FORMS\",\"key\":\"form\",\"controller\":\"form\",\"getter\":\"getallform\",\"actions\":[{\"action\":\"duplicateform\",\"label\":\"COM_EMUNDUS_ONBOARD_ACTION_DUPLICATE\",\"controller\":\"form\",\"name\":\"duplicate\"},{\"action\":\"index.php?option=com_emundus&view=form&layout=formbuilder&prid=%id%\",\"label\":\"COM_EMUNDUS_ONBOARD_MODIFY\",\"controller\":\"form\",\"type\":\"redirect\",\"name\":\"edit\"},{\"action\":\"createform\",\"controller\":\"form\",\"label\":\"COM_EMUNDUS_ONBOARD_ADD_FORM\",\"name\":\"add\"}],\"filters\":[]},{\"title\":\"COM_EMUNDUS_FORM_MY_EVAL_FORMS\",\"key\":\"form_evaluations\",\"controller\":\"form\",\"getter\":\"getallgrilleEval\",\"actions\":[{\"action\":\"createformeval\",\"label\":\"COM_EMUNDUS_ONBOARD_ADD_EVAL_FORM\",\"controller\":\"form\",\"name\":\"add\"},{\"action\":\"\\/index.php?option=com_emundus&view=form&layout=formbuilder&prid=%id%&mode=eval\",\"label\":\"COM_EMUNDUS_ONBOARD_MODIFY\",\"controller\":\"form\",\"type\":\"redirect\",\"name\":\"edit\"}],\"filters\":[]},{\"title\":\"COM_EMUNDUS_FORM_PAGE_MODELS\",\"key\":\"form_models\",\"controller\":\"formbuilder\",\"getter\":\"getallmodels\",\"actions\":[{\"action\":\"deleteformmodelfromids\",\"label\":\"COM_EMUNDUS_ACTIONS_DELETE\",\"controller\":\"formbuilder\",\"parameters\":\"&model_ids=%id%\",\"name\":\"delete\"},{\"action\":\"\\/index.php?option=com_emundus&view=form&layout=formbuilder&prid=%form_id%&mode=models\",\"label\":\"COM_EMUNDUS_ONBOARD_MODIFY\",\"controller\":\"form\",\"type\":\"redirect\",\"name\":\"edit\"}],\"filters\":[]}]},\"campaigns\":{\"title\":\"COM_EMUNDUS_ONBOARD_CAMPAIGNS\",\"tabs\":[{\"title\":\"COM_EMUNDUS_ONBOARD_CAMPAIGNS\",\"key\":\"campaign\",\"controller\":\"campaign\",\"getter\":\"getallcampaign\",\"actions\":[{\"action\":\"index.php?option=com_emundus&view=campaigns&layout=add\",\"label\":\"COM_EMUNDUS_ONBOARD_ADD_CAMPAIGN\",\"controller\":\"campaign\",\"name\":\"add\",\"type\":\"redirect\"},{\"action\":\"duplicatecampaign\",\"label\":\"COM_EMUNDUS_ONBOARD_ACTION_DUPLICATE\",\"controller\":\"campaign\",\"name\":\"duplicate\"},{\"action\":\"index.php?option=com_emundus&view=campaigns&layout=addnextcampaign&cid=%id%\",\"label\":\"COM_EMUNDUS_ONBOARD_MODIFY\",\"controller\":\"campaign\",\"type\":\"redirect\",\"name\":\"edit\"},{\"action\":\"deletecampaign\",\"label\":\"COM_EMUNDUS_ONBOARD_ACTION_DELETE\",\"controller\":\"campaign\",\"name\":\"delete\",\"confirm\":\"COM_EMUNDUS_ONBOARD_CAMPDELETE\",\"showon\":{\"key\":\"nb_files\",\"operator\":\"<\",\"value\":\"1\"}},{\"action\":\"unpublishcampaign\",\"label\":\"COM_EMUNDUS_ONBOARD_ACTION_UNPUBLISH\",\"controller\":\"campaign\",\"name\":\"unpublish\",\"showon\":{\"key\":\"published\",\"operator\":\"=\",\"value\":\"1\"}},{\"action\":\"publishcampaign\",\"label\":\"COM_EMUNDUS_ONBOARD_ACTION_PUBLISH\",\"controller\":\"campaign\",\"name\":\"publish\",\"showon\":{\"key\":\"published\",\"operator\":\"=\",\"value\":\"0\"}},{\"action\":\"pincampaign\",\"label\":\"COM_EMUNDUS_ONBOARD_ACTION_PIN_CAMPAIGN\",\"controller\":\"campaign\",\"name\":\"pin\",\"icon\":\"push_pin\",\"iconOutlined\":true,\"showon\":{\"key\":\"pinned\",\"operator\":\"!=\",\"value\":\"1\"}},{\"action\":\"unpincampaign\",\"label\":\"COM_EMUNDUS_ONBOARD_ACTION_UNPIN_CAMPAIGN\",\"controller\":\"campaign\",\"name\":\"unpin\",\"icon\":\"push_pin\",\"iconOutlined\":false,\"showon\":{\"key\":\"pinned\",\"operator\":\"=\",\"value\":\"1\"}}],\"filters\":[{\"label\":\"COM_EMUNDUS_ONBOARD_FILTER_ALL\",\"getter\":\"\",\"controller\":\"campaigns\",\"key\":\"filter\",\"values\":[{\"label\":\"COM_EMUNDUS_ONBOARD_FILTER_ALL\",\"value\":\"all\"},{\"label\":\"COM_EMUNDUS_CAMPAIGN_YET_TO_COME\",\"value\":\"yettocome\"},{\"label\":\"COM_EMUNDUS_ONBOARD_FILTER_OPEN\",\"value\":\"ongoing\"},{\"label\":\"COM_EMUNDUS_ONBOARD_FILTER_CLOSE\",\"value\":\"Terminated\"},{\"label\":\"COM_EMUNDUS_ONBOARD_FILTER_